	POWER_ASPECT_OF_SOL_L4A_DESC = "Tăng {b.upgrades.power_aspect_of_sol.l4a.s_duration_factor}% thời gian hiệu lực của bùa khích lệ.",
	POWER_ASPECT_OF_SOL_L3_NAME = "Chiến đấu",
	POWER_ASPECT_OF_SOL_L3_DESC = "Hiện thân Sol khích lệ đồng minh gần đó, tăng {b.powers.aspect_of_sol.warcry.s_dmg_factor_inc}% sát thương và {b.powers.aspect_of_sol.warcry.armor_inc}% giáp trong {b.powers.aspect_of_sol.warcry.duration} giây.",
	POWER_ASPECT_OF_SOL_L2B_NAME = "Sức mạnh ban đầu",
	POWER_ASPECT_OF_SOL_L2B_DESC = "Tăng {b.upgrades.power_aspect_of_sol.l2b.s_damage_inc}% sát thương của hiện thân Sol.",
	HERO_CONNOR_TALENT_1_DESCRIPTION = "Khi còn dưới {b.heroes.hero_connor.talent_1.hp_ptg_to_trigger}% máu, Connor được tăng {b.heroes.hero_connor.talent_1.s_skill_damage_factor}% sát thương kỹ năng.",
	TOWER_STAGE_17_JOUST_NAME = "JOUSTING STAND",
	POWER_ASPECT_OF_SOL_DESC = "Khi tình thế nguy cấp, có thể triệu hồi hiện thân của Sol, thánh kỵ sĩ đầu tiên được Đấng Mang Ánh Sáng ban phước, đến chiến trường. Búa thánh của ngài sẽ sát cánh cùng những người chính nghĩa.",
	HERO_ZEFIRA_SKILL_C_2_TITLE = "ASTRAL BLINK II",
	LEVEL_264_HISTORY = "Đến điểm đến tiếp theo, chúng tôi đến Vardulder. Đây là nơi ẩn náu của người chủ của Blackburn, những người đã phải đối mặt với sự nguyền rủa cổ đại – những người chết ở đây không thể nghỉ ngơi.\n\nTuy nhiên, ngay cả thành phố này cũng bị quân đội Vez'nan tấn công, ý định của Vez'nan không rõ, ngay cả các đồng minh tiềm năng của chúng ta cũng đã trở thành mục tiêu của ông.",
	ENEMY_DEMON_LORD_G6_EXTRA = "- Bảo vệ xung quanh ma quỷ\n- Giúp chống lại các tác dụng độc hại, nguyền rủa, giảm tốc độ\n- Đáng kháng phép cao",
	CREDITS_TITLE_04_STORY_WRITERS = "Thị trường",
