	HERO_CONNOR_SKILL_C_3_TITLE = "EARTHSHATTER III",
	OPTIONS_PAGE_CONTROLS = "Thiết lập điều khiển",
	NOTIFICATION_title_special = "Khả năng đặc biệt được mở ra",
	ENEMY_SKELETON_BIG_G6_DESCRIPTION = "Kẻ địch càng lớn, bộ xương càng to và cứng cáp để hắc pháp sư hồi sinh.",
	POWER_MUSKETEERS_NAME = "Thợ Súng Vương",
	ENEMY_DEMON_HOUND_NAME = "Demon Hound",
	ENEMY_DEMON_IMP_G6_NAME = "Demon Imp",
	HERO_CONNOR_CLASS = "Đền chiến binh",
	TOWER_MUSKETEERS_SHRAPNEL_NAME_2 = "SHRAPNEL SHOT II",
	ENEMY_NECROMANCER_G6_DESCRIPTION = "Cái chết không phải giới hạn với pháp sư chiêu hồn, những kẻ dùng người ngã xuống để bổ sung quân số.",
	NOTIFICATION_rally_point_desc_body_3 = "Sau đó nhấp chuột hoặc kéo đến vị trí mục tiêu mới.",
	HERO_ASHBITE_DESC = "Sau hành trình trước, rồng đỏ Ashbite kết thân với Hoàng tử Denas và binh sĩ. Anh theo họ từ phương Nam lên phương Bắc và tuyên thệ trung thành với hoàng gia Linirea.",
