	ENEMY_DARK_KNIGHT_G6_DESCRIPTION = "Họ từng chỉ còn một bước nữa là trở thành thánh kỵ sĩ, nhưng đã từ bỏ lời thề bảo hộ để tôn thờ giáo luật chinh phục.",
	QUIT = "Thoát",
	NOTIFICATION_hero_desc_body_1 = "Anh hùng là một đơn vị ưu tú, có thể đối mặt với kẻ địch mạnh mẽ và hỗ trợ lực lượng của bạn.",
	NOTIFICATION_desktop_rain_of_fire_desc_body = "Các thiên thạch sẽ hạ xuống từ trời để tấn công kẻ địch, nhấp vào con đường để được đưa ra.",
	ENEMY_GARGOYLE_G6_DESCRIPTION = "Những tượng hộ vệ nhà thờ bị hắc thuật đánh thức, giờ gieo nỗi kinh hoàng cho dân làng.",
