	POWER_TELEPORTATION_SIGIL_L2A_NAME = "Khác lại",
	LEVEL_255_HISTORY = "Đối với các linh hồn, cây bạc vĩ đại luôn là một biểu tượng quan trọng của mối quan hệ của họ với thiên nhiên. Như một đồng minh, đối mặt với mối đe dọa của Vez'nan, họ chắc chắn sẽ giúp đỡ nhau.\n\nTuy nhiên, người động vật dường như đã gia nhập lực lượng của Vez'nan, đang chuẩn bị để phá hủy trong làng bạc. chúng tôi không bao giờ để họ thành công!",
	BUTTON_RESTART = "Chơi lại",
	MAP_INAPP_GEM_PACK_3 = "Thùng ngọc",
	TOWER_ALCHEMIST_4_SKILL_B_1_DESCRIPTION = "Gọi trợ thủ uống thuốc biến thành người khổng lồ, có {b.towers.alchemist.skill_b.soldier.hp[1]} máu và gây {b.towers.alchemist.skill_b.soldier.basic_attack.damage_min[1]}–{b.towers.alchemist.skill_b.soldier.basic_attack.damage_max[1]} sát thương chuẩn. Tái xuất sau {b.towers.alchemist.skill_b.cooldown[1]} giây kể từ khi biến mất.",
