	TOWER_SUNRAY_4_ULT_DESCRIPTION = "Gọi {b.towers.sunray_master.ultimate.number_of_beams} tia mặt trời chiếu xuống vùng mục tiêu. Mỗi tia gây {b.towers.sunray_master.ultimate.damage_min}–{b.towers.sunray_master.ultimate.damage_max} sát thương chuẩn và làm choáng {b.towers.sunray_master.ultimate.stun.duration} giây.",
	HERO_RHODES_TALENT_2_TITLE = "UNSTOPPABLE",
	HERO_RHODES_SKILL_A_2_DESCRIPTION = "Bắn tia sáng từ viên ngọc, gây {b.heroes.hero_rhodes.upgrades.upg_sa1.damage_min}–{b.heroes.hero_rhodes.upgrades.upg_sa1.damage_max} sát thương chuẩn lên một kẻ địch. Giảm hồi chiêu còn {b.heroes.hero_rhodes.upgrades.upg_sa1.cooldown} giây.",
