	SOLDIER_STAGE_08_TEMPLAR_SWORSDMAN_4_NAME = "DE BRUS",
	LEVEL_262_HISTORY = "Con đường đến đền thờ, không chỉ đầy những ngọn núi mọc và những ngọn đồi khủng khiếp. lần này cũng dẫn chúng ta thẳng đến ngọn đầm cũ của ma quỷ.\n\nVì họ đã chiếm được đất, chúng ta nên cẩn thận hơn để tránh những gì họ mang lại cho chúng ta. Hãy đứng dậy, tướng!",
