	HERO_GERALD_G6_SKILL_C_2_DESCRIPTION = "Dùng Time Relic để thoát chết, hồi {b.heroes.hero_gerald.upgrades.upg_sc1.hp_ptg}% máu tối đa và đẩy kẻ tấn công lùi về phía sau. Giảm hồi chiêu còn {b.heroes.hero_gerald.upgrades.upg_sc1.cooldown} giây.",
	LEVEL_260_HISTORY = "Khi chúng ta bị quỷ dữ đuổi, chúng ta đã đến một hang động rộng mở. Mặt trời lặn ra khỏi hang, lặn lên trên hồ rộng và đông lạnh.\n\nTuy nhiên, nhiều xương sống được phân tán xung quanh, cho thấy đây có thể là một cái nồi nguy hiểm của một con quái vật. Nhấn xuống, nhanh chóng qua đây.",
