	TOWER_CATAPULT_4_ULT_DESCRIPTION = "Ném đá cháy lăn dọc đường, gây {b.towers.catapult.ultimate.s_total_damage} sát thương nổ và thiêu đốt mục tiêu với {b.towers.catapult.ultimate.burn.s_damage} sát thương chuẩn trong {b.towers.catapult.ultimate.burn.duration} giây.",
	LEVEL_251_HISTORY = "Chị tướng, tôi được truyền đi, để cảnh báo cho vua Linirea, và Vez'nan sẽ mang lại một tương lai tàn phá.\n\nTuy nhiên, ngay khi tôi đến, lâu đài Linirea đang bị trục trặc bởi những kẻ trộm, và bây giờ chúng ta phải dừng lại trước khi các kẻ trột đe dọa!",
