	LEVEL_261_HISTORY = "Sau khi ở hồ, chúng tôi rơi vào sâu núi. Một giọt nước trong không khí, không thể mở tay ra trong bóng tối, bao phủ trong hang này.\n\nMột tiếng kêu quen thuộc đến từ các đường lối trong hang, chậm rãi bao quanh quân đội của chúng ta. Hãy nhanh chóng xây dựng trại sẵn sàng, kẻ địch sẽ đến với chúng tôi bất cứ lúc nào!",
	LEVEL_268_HISTORY = "Ta đã đến Arcania kịp thời; Vez'nan vẫn chưa thực hiện được âm mưu mở hoàn toàn Khe Nứt Tro Tàn. Nhưng sự im lặng trong thành phố này… thật bất thường.\n\nDù sao, nhiệm vụ trước mắt vẫn là đánh bại quân đội Vez'nan và phá hủy Giọt lệ Elynie. Hãy đưa lịch sử tương lai trở lại đúng hướng!",
